public List<String> weightedUniformStrings(String s, int[] queries) {
    List<String> res = new ArrayList<>();
    for (int q : queries) {
        boolean found = false;
        int running = 0;
        char prev = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            running = (c == prev) ? running + (c - 'a' + 1) : (c - 'a' + 1);
            prev = c;
            if (running == q) { found = true; break; }
        }
        res.add(found ? "Yes" : "No");
    }
    return res;
}

public List<String> weightedUniformStrings(String s, int[] queries) {
    Set<Integer> seen = new HashSet<>();
    int running = 0;
    char prev = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int w = c - 'a' + 1;
        running = (c == prev) ? running + w : w;
        seen.add(running);
        prev = c;
    }
    List<String> res = new ArrayList<>();
    for (int q : queries) {
        res.add(seen.contains(q) ? "Yes" : "No");
    }
    return res;
}
